const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const salta = ee.FeatureCollection('FAO/GAUL/2015/level1')
    .filter(ee.Filter.and(
      ee.Filter.eq('ADM0_NAME', 'Argentina'),
      ee.Filter.eq('ADM1_NAME', 'Salta')
    ));

  const geom = salta.geometry();

  // 2. Data Acquisition - Hansen Global Forest Change
  const hansen = ee.Image('UMD/hansen/global_forest_change_2023_v1_11');

  // 3. Processing
  // Tree cover in 2000 (threshold: >30% is forest)
  const treecover2000 = hansen.select('treecover2000');
  const forestMask2000 = treecover2000.gt(30);

  // Forest loss from 2001-2019 (lossyear: 1-19)
  const loss = hansen.select('loss');
  const lossyear = hansen.select('lossyear');
  const loss2001to2019 = loss.and(lossyear.gte(1)).and(lossyear.lte(19));

  // Calculate forest area in 2000
  const forestArea2000 = forestMask2000.multiply(ee.Image.pixelArea());
  const totalForest2000 = forestArea2000.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geom,
    scale: 3000,
    maxPixels: 1e9
  }).get('treecover2000');

  // Calculate forest loss area 2001-2019
  const lossArea = loss2001to2019.multiply(ee.Image.pixelArea());
  const totalLoss = lossArea.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geom,
    scale: 3000,
    maxPixels: 1e9
  }).get('loss');

  // Count valid pixels
  const pixelCount = forestMask2000.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geom,
    scale: 3000,
    maxPixels: 1e9
  }).get('treecover2000');

  // 4. Get results
  const forest2000_val = await totalForest2000.getInfo();
  const loss_val = await totalLoss.getInfo();
  const pixels = await pixelCount.getInfo();

  // 5. Validation & Final Answer
  console.log(`Salta Province Forest Analysis (2000-2019)`);
  console.log(`Valid pixels: ${pixels}`);

  if (pixels === null || pixels === 0) {
    console.log('No valid pixels found');
    console.log('<answer>C2</answer>');
    return;
  }

  if (forest2000_val === null || loss_val === null) {
    console.log('Calculation failed - null result');
    console.log('<answer>C3</answer>');
    return;
  }

  const forest2000_ha = (forest2000_val / 10000).toFixed(0);
  const loss_ha = (loss_val / 10000).toFixed(0);
  const loss_pct = ((loss_val / forest2000_val) * 100).toFixed(2);

  console.log(`Forest cover 2000: ${forest2000_ha} ha`);
  console.log(`Forest loss 2001-2019: ${loss_ha} ha`);
  console.log(`Loss percentage: ${loss_pct}%`);

  if (loss_val > 0) {
    console.log('Forest cover decreased significantly');
    console.log('<answer>A</answer>');
  } else {
    console.log('No forest loss detected');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
